import{_ as a,o as t,c as i,a6 as o}from"./chunks/framework.CKIbuWFA.js";const u=JSON.parse('{"title":"Collaboration authority and authentication","description":"","frontmatter":{"title":"Collaboration authority and authentication","docId":"developer.collaboration","translationKey":"developer.collaboration","locale":"en","audience":"developer","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"fb71673a581e923e3c02ae401a46937b007f9919690ca020d22c27b370b6c61d","translationRevision":"fb71673a581e923e3c02ae401a46937b007f9919690ca020d22c27b370b6c61d","order":190},"headers":[],"relativePath":"en/developer/collaboration.md","filePath":"en/developer/collaboration.md","lastUpdated":1794611623000}'),n={name:"en/developer/collaboration.md"};function s(r,e,l,d,c,p){return t(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="collaboration-authority-and-authentication" tabindex="-1">Collaboration authority and authentication <a class="header-anchor" href="#collaboration-authority-and-authentication" aria-label="Permalink to &quot;Collaboration authority and authentication {#collaboration-authority-and-authentication}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Goal and prerequisites {#goal-and-prerequisites}&quot;">​</a></h2><p>Allow an approved device to inspect or perform a narrowly scoped operation on an existing host. Use a test owner profile, a build with remote support and a configured transport. Account login, Cloud team membership, local ownership and a direct delegated session are distinct authorities.</p><h2 id="establish-the-trust-chain" tabindex="-1">Establish the trust chain <a class="header-anchor" href="#establish-the-trust-chain" aria-label="Permalink to &quot;Establish the trust chain {#establish-the-trust-chain}&quot;">​</a></h2><p>Local-owner <code>collaboration.*</code> administration owns configuration, invitations, pending requests, principals, grants, sessions and audit. Discover schemas before configuring a listener or creating credentials:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> collaboration.configure</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> collaboration.invites.create</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> collaboration.status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{}&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json</span></span></code></pre></div><p>An invitation initiates pairing; it does not itself grant business authority. Owner approval creates the appropriate session/grants. Direct HTTPS requires validated certificates or explicitly pinned native trust. Native bearer and browser cookie boundaries differ. The initial <code>collaboration.hello</code> binds protocol, host instance, principal, session, grant revision, capabilities and negotiated limits.</p><h2 id="authorize-each-operation" tabindex="-1">Authorize each operation <a class="header-anchor" href="#authorize-each-operation" aria-label="Permalink to &quot;Authorize each operation {#authorize-each-operation}&quot;">​</a></h2><p>A supported remote method must pass its allowlist, capability, resource restriction and current-session checks. Workflow disable/delete use durable compare-and-set metadata. Points adjustments are additive and have their own grant limits. Remote automation reads are closed summaries; disabled author-owned drafts cannot acquire executable owner authority merely by being saved.</p><p>Owner review/adoption and checked approval bind current definitions, dependencies and provenance. A preview manifest reports inspection data, not an execution token. Revalidate grants and resource bindings at execution boundaries rather than treating transport identity as permanent permission.</p><h2 id="expected-result-and-status" tabindex="-1">Expected result and status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Expected result and status {#expected-result-and-status}&quot;">​</a></h2><p>Direct native collaboration has implemented scoped reads, selected durable mutations and bounded recovery. Cloud teams/relay additionally have their own adapters; the documented Cloud relay read path must not be presented as full moderation or draft execution. Remaining delegated effects, domain writes and multi-PC acceptance stay experimental. See <a href="./remote-client.html">remote clients</a> and <a href="./cloud.html">Cloud</a> for the selected path.</p><h2 id="recover-and-verify" tabindex="-1">Recover and verify <a class="header-anchor" href="#recover-and-verify" aria-label="Permalink to &quot;Recover and verify {#recover-and-verify}&quot;">​</a></h2><p>On revocation or identity change, stop subscriptions and discard private projections. Use <code>collaboration.subscribe</code>, <code>snapshot</code> and <code>resume</code> according to negotiated domains and cursor validity. Resolve the original command ID after an uncertain acknowledgement. Do not retry a delete with a new ID or restore authority from an old receipt. The <a href="https://github.com/nglmercer/TikTools-app/tree/remake/crates/tiktools-collaboration/src" target="_blank" rel="noreferrer">authorization source</a> and registry policy define the boundary; passing TLS alone is not an authorization test.</p><h2 id="operational-details" tabindex="-1">Operational details <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Operational details {#operational-details}&quot;">​</a></h2><p>Teams sequence: register the device, issue/join an invitation or access request, approve it, then have the host confirm the native permission’s current revision. <code>pendingHost</code> means this last step is outstanding. A new permission revision invalidates the previous confirmation; reload on stale expectedRevision. Native acceptance requires a fresh snapshot, active host/device, active permission and confirmedRevision equal to revision. The UI exposes host/join panels and available approvals; native confirmation is an API contract, not a promised button on every build.</p><p>Legacy role conversion is closed: observer grants live/workflow/points/competition/automation/outcome reads; moderator adds points adjustment, workflow toggle, automation toggle and competition management; automationEditor adds automation editing to the reads. No preset implies arbitrary scripts, external effects or reusable automation delegation. Explicit <code>nativeGrant</code> requires role <code>custom</code>; restrict resources, effect scopes and points delta there. Native client kind is only <code>desktop</code> or <code>agent</code>. Unsupported policies fail rather than expanding rights. Diagnose pairing, host confirmation, revision freshness and transport separately.</p>`,17)])])}const m=a(n,[["render",s]]);export{u as __pageData,m as default};
